if not (a > h):
    return (False, None)
b2 = a*a - h*h
if b2 <= 0:
    return (False, None)
# w2 inside w1: 2h + r2 <= r1
if 2*h + r2 > r1:
    return (False, None)
# Origin outside ellipse
