    return (False, None)
# Minimal positive slope occurs when y=mx is tangent from origin to the ellipse |XC1|+|XC2|=r1+r2
# For symmetric foci at (-h,k) and (h,k), with center M=(0,k), in centered coordinates O'=(0,-k),
