m = math.sqrt(m2_num/m2_den)
y0 = -k
Acoef = 1.0/(a*a) + (m*m)/b2
Bcoef = 2.0*m*y0/b2
x_t = -Bcoef/(2.0*Acoef)
y_t = m*x_t + y0
d_to_F2 = math.hypot(x_t - h, y_t)
new_r = d_to_F2 - r2
if new_r < 1e-10:
    # Degenerate or invalid tangency configuration
    return (False, None)
# Difficulty gating: ensure the fraction is nontrivial (not equal to 1, not tiny)
frac = Fraction(m2_num, m2_den)
p, q = frac.numerator, frac.denominator
if p <= 1 or q <= 1 or p == q:
    return (False, None)
answer = p + q
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

